{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Zidovudine absolute oral bioavailability was 61% in infants >14 days, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Isosorbide 5-mononitrate absolute systemic availability was 100% after oral solution in young healthy subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Tacrolimus absolute oral bioavailability was 18.8% in white subjects after a 5 mg oral capsule, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most transferred evidence shows absolute or systemic oral bioavailability ≥20%, often 45–100%, supporting high bioavailability. One tacrolimus absolute record is below 20%, but the preponderance of high-quality transferred evidence supports F ≥20%.",
  "evidence_gaps": [
    "Molecule 1 records refer to multiple distinct drugs (theophylline, amphotericin B, posaconazole, voriconazole); provenance conflict prevents assigning a direction.",
    "Molecule 9 records refer to both clavulanic acid and amoxicillin; provenance conflict prevents assigning a direction.",
    "Tacrolimus (Molecule 5) has mixed numeric records, with some absolute estimates below 20% and other reports of 23–31%; direction was assigned from the strongest absolute record."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

